const files = [
  "/app/fixture/README.md",
  "/app/fixture/package.json",
  "/app/fixture/release-log.md",
  "/app/fixture/git-tags.txt",
  "/app/fixture/client-bundle-excerpt.js",
  "/app/fixture/lib-index-excerpt.js",
  "/app/fixture/asset-route-probe.txt",
  "/app/fixture/session-log-excerpt.txt"
];
const rs = await Promise.all(files.map(cmd => tools.exec_command({cmd:`sed -n '1,260p' '${cmd}'`,workdir:"/app",yield_time_ms:10000,max_output_tokens:20000})));
for (let i=0;i<rs.length;i++) { text(`\n===== ${files[i]} =====\n${rs[i].output}`); }

