const rs = await Promise.all([
  tools.exec_command({cmd:"sed -n '1,320p' /app/agent-output/S19-phantom-update-stale-host/report.md","workdir":"/app","yield_time_ms":10000,"max_output_tokens":30000}),
  tools.exec_command({cmd:"git status --short; git diff --check; git diff -- /app/fixture","workdir":"/app","yield_time_ms":10000,"max_output_tokens":10000}),
  tools.exec_command({cmd:"sha256sum /app/fixture/*","workdir":"/app","yield_time_ms":10000,"max_output_tokens":10000})
]);
text(`===== report =====\n${rs[0].output}\n===== verification =====\n${rs[1].output}\n===== fixture hashes =====\n${rs[2].output}`);
